/**
 * POST /api/latex  (body: the .tex source)  →  application/pdf
 *
 * Compiles the CV's LaTeX with pdflatex on a public LaTeX service, because
 * Vercel and similar hosts have no TeX installed. Tries, in order:
 *   1. LATEX_COMPILE_URL, if you run your own LaTeX-on-HTTP server
 *   2. latex.ytotech.com   (LaTeX-on-HTTP, JSON API)
 *   3. texlive.net          (TeXLive.net latexcgi, form API)
 * Only documents generated by this site's CV (they start with the marker
 * line) are accepted, so the route cannot be used as a general compiler.
 */
import { LATEX_MARKER } from '@/lib/cv';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

const MAX_BYTES = 300_000; // .tex source
const TIMEOUT = 45_000;

async function withTimeout(promise, ms = TIMEOUT) {
  let t;
  try {
    return await Promise.race([promise, new Promise((_, rej) => (t = setTimeout(() => rej(new Error('timeout')), ms)))]);
  } finally {
    clearTimeout(t);
  }
}

const isPdf = (buf) => buf.byteLength > 4 && Buffer.from(buf.slice(0, 4)).toString() === '%PDF';

async function ytotech(texSource, base = 'https://latex.ytotech.com', files = []) {
  const res = await withTimeout(
    fetch(`${base.replace(/\/$/, '')}/builds/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ compiler: 'pdflatex', resources: [{ main: true, content: texSource }, ...files.map((f) => (f.file ? { path: f.path, file: f.file } : { path: f.path, url: f.url }))] }),
    })
  );
  const buf = await res.arrayBuffer();
  if (res.ok && isPdf(buf)) return buf;
  throw new Error(`ytotech ${res.status}: ${Buffer.from(buf).toString('utf8').slice(0, 300)}`);
}

async function texliveNet(texSource) {
  const form = new FormData();
  form.append('filecontents[]', texSource);
  form.append('filename[]', 'document.tex');
  form.append('engine', 'pdflatex');
  form.append('return', 'pdf');
  const res = await withTimeout(fetch('https://texlive.net/cgi-bin/latexcgi', { method: 'POST', body: form }));
  const buf = await res.arrayBuffer();
  if (res.ok && isPdf(buf)) return buf;
  throw new Error(`texlive.net ${res.status}`);
}

/** Extra files the document uses (the header photo): a public https image, or base64 bytes (max ~3 MB). */
function cleanFiles(list) {
  return (Array.isArray(list) ? list : [])
    .filter((f) => f && /^photo\.(jpg|png)$/.test(f.path))
    .filter((f) =>
      f.file
        ? typeof f.file === 'string' && f.file.length < 4_000_000 && /^[A-Za-z0-9+/=]+$/.test(f.file)
        : /^https:\/\/[^\s]+$/.test(f.url || '') && !/^https:\/\/(localhost|127\.|10\.|192\.168\.)/.test(f.url)
    )
    .slice(0, 1);
}

export async function POST(request) {
  // Body: the .tex source, or JSON { tex, files: [{ path: 'photo.jpg', url }] }.
  const raw = await request.text();
  let texSource = raw;
  let files = [];
  if (raw.startsWith('{')) {
    try {
      const body = JSON.parse(raw);
      texSource = String(body.tex || '');
      files = cleanFiles(body.files);
    } catch {
      texSource = '';
    }
  }
  if (!texSource || texSource.length > MAX_BYTES || !texSource.startsWith(LATEX_MARKER)) {
    return Response.json({ error: 'Only CV documents generated by this site can be compiled.' }, { status: 400 });
  }
  // With the photo first; if the photo cannot be fetched, the same compiler without it
  // (the document shows no photo when the file is missing, it never fails on it).
  const attempts = [
    process.env.LATEX_COMPILE_URL && files.length && (() => ytotech(texSource, process.env.LATEX_COMPILE_URL, files)),
    process.env.LATEX_COMPILE_URL && (() => ytotech(texSource, process.env.LATEX_COMPILE_URL)),
    files.length && (() => ytotech(texSource, undefined, files)),
    () => ytotech(texSource),
    () => texliveNet(texSource),
  ].filter(Boolean);
  const errors = [];
  for (const attempt of attempts) {
    try {
      const pdf = await attempt();
      return new Response(pdf, { headers: { 'Content-Type': 'application/pdf', 'Cache-Control': 'no-store' } });
    } catch (err) {
      errors.push(err.message);
    }
  }
  console.warn('[latex] all compilers failed:', errors);
  return Response.json({ error: 'The LaTeX compiler could not be reached. Use “Open in Overleaf” or download the .tex instead.', details: errors }, { status: 502 });
}
